import { USERS, expect, expectStatus, test } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  test("a page past the last vendor is empty but still reports the total", { tag: "@LIF-15" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");

    const firstResponse = await member.get("/api/vendors", { params: { limit: 1, offset: 0 } });
    const first = await expectStatus<{ items: unknown[]; total: number; limit: number; offset: number }>(firstResponse, 200);
    const offset = first.total + 1000;

    // Act
    const response = await member.get("/api/vendors", { params: { limit: 20, offset } });

    // Assert
    const page = await expectStatus<{ items: unknown[]; total: number; limit: number; offset: number }>(response, 200);
    expect(page.items).toEqual([]);
    expect(page.total).toBe(first.total);
    expect(page.offset).toBe(offset);
  });
});
